            aCross = TwistMix64::DiffuseB((aCross ^ aTwistDomainWordCross));
            //
            aScatter = (RotL64(aIngress, 19U) ^ RotL64(aCross, 47U)) + (RotL64(aPrevious, 34U) + RotL64(aCarry, 3U));
            aScatter = TwistMix64::DiffuseB((aScatter ^ aTwistDomainWordScatter));
            //
            aOrbiterB = ((aWandererG + RotL64(aCross, 5U)) + 0xF29D4634A4459048ULL) + aOASaltF[(((511U - aIndex) + 71U)) & S_SALT1];
            aOrbiterC = ((aWandererE + RotL64(aScatter, 53U)) + 0xFE7714B0DEFAC4D8ULL) + aOASaltH[((aIndex + 280U)) & S_SALT1];
            aOrbiterJ = ((aWandererI + RotL64(aPrevious, 19U)) + RotL64(aCarry, 53U)) + 0x47A8B29AC04DAB91ULL;
            aOrbiterH = ((aWandererH + RotL64(aIngress, 35U)) + RotL64(aCarry, 41U)) + 0xD579413A99124ED4ULL;
            aOrbiterD = (aWandererA + RotL64(aScatter, 41U)) + 0x4998FE27D49C13E1ULL;
            aOrbiterF = (aWandererD + RotL64(aIngress, 12U)) + 0x619C177116B1E7B0ULL;
            aOrbiterG = (((aWandererC + RotL64(aCross, 29U)) + RotL64(aCarry, 23U)) + 0xBE48FC5743663A1DULL) + aOASaltE[(((511U - aIndex) + 440U)) & S_SALT1];
            //
            aOrbiterB = (aOrbiterB + aOrbiterC) + 0xEE95B0C777E29194ULL;
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterB) ^ 0x872701DD6EC87772ULL) ^ aOUSaltE[((aIndex + 339U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0x2627DD4DC2811E45ULL), 21U);
